/**
 * Background sweep runner — keeps housekeeping OFF the job-claim path.
 *
 * Until 2026-10-01 every sweep (billing, ssh-health, player-tracking, geo, SEO,
 * monitor…) ran INLINE at the top of worker/index.ts's `for(;;)` loop, before
 * the loop got around to claiming jobs. One slow sweep delayed every claim:
 * confirmed live, a GAME_CONFIG queued at 04:47 UTC was not claimed until
 * 04:53 because the loop was inside ssh-health + player-tracking (each burning
 * 30-60s on SSH auth failures against two servers) and a billing card retry.
 * The customer saw "Applying…" for six minutes for a 30-second job.
 *
 * Now each sweep is its own independent async timer loop:
 *   - overlap guard: a sweep's next run is scheduled only after the previous
 *     one has settled, so a slow sweep can never pile up on itself;
 *   - per-sweep timeout: the runner stops WAITING on a sweep that overruns
 *     (frees its concurrency slot, logs it) — the promise itself is left to
 *     finish or fail on its own, because none of the sweeps are cancellable,
 *     and the overlap guard still prevents a second instance starting until
 *     it does settle;
 *   - global concurrency cap: at most `maxConcurrent` sweeps run at once, so
 *     a boot (where every sweep is due at t=0) doesn't open 40 SSH/Proxmox
 *     fan-outs simultaneously alongside the job slots;
 *   - isolation: a sweep's throw is logged with its name and never affects
 *     another sweep or the job loop.
 *
 * Nothing here knows about jobs; worker/index.ts registers the sweeps and
 * calls `start()`, and `stop()` on graceful shutdown.
 */

export type SweepDef = {
  name: string;
  /** Minimum time between the START of one run and the START of the next. */
  intervalMs: number;
  fn: () => Promise<unknown>;
  /** How long the runner waits before declaring the run overrun (default 5 min). */
  timeoutMs?: number;
  /** Delay before the first run (default 0 — matches the old `lastX = 0` boot-time behaviour). */
  initialDelayMs?: number;
};

export type SweepStats = {
  name: string;
  runs: number;
  errors: number;
  overruns: number;
  running: boolean;
  lastStartedAt: number | null;
  lastDurationMs: number | null;
  maxDurationMs: number;
};

type SweepState = SweepStats & {
  def: SweepDef;
  timer: NodeJS.Timeout | null;
  /** Pending run still settling after an overrun — next run must wait for it. */
  settling: Promise<unknown> | null;
};

export type SweepRunnerOptions = {
  maxConcurrent: number;
  defaultTimeoutMs?: number;
  log?: (msg: string) => void;
  logError?: (msg: string, err?: unknown) => void;
  /** Injected clock/timers for tests. */
  now?: () => number;
  setTimeoutFn?: typeof setTimeout;
  clearTimeoutFn?: typeof clearTimeout;
};

export class SweepRunner {
  private sweeps = new Map<string, SweepState>();
  private running = 0;
  private waiters: Array<() => void> = [];
  private started = false;
  private stopped = false;
  private readonly opts: Required<SweepRunnerOptions>;

  constructor(opts: SweepRunnerOptions) {
    this.opts = {
      maxConcurrent: Math.max(1, opts.maxConcurrent),
      defaultTimeoutMs: opts.defaultTimeoutMs ?? 5 * 60_000,
      log: opts.log ?? ((m) => console.log(m)),
      logError: opts.logError ?? ((m, e) => console.error(m, e)),
      now: opts.now ?? Date.now,
      setTimeoutFn: opts.setTimeoutFn ?? setTimeout,
      clearTimeoutFn: opts.clearTimeoutFn ?? clearTimeout,
    };
  }

  register(def: SweepDef): this {
    if (this.sweeps.has(def.name)) throw new Error(`sweep "${def.name}" registered twice`);
    this.sweeps.set(def.name, {
      def,
      name: def.name,
      runs: 0,
      errors: 0,
      overruns: 0,
      running: false,
      lastStartedAt: null,
      lastDurationMs: null,
      maxDurationMs: 0,
      timer: null,
      settling: null,
    });
    if (this.started && !this.stopped) this.schedule(this.sweeps.get(def.name)!, def.initialDelayMs ?? 0);
    return this;
  }

  start(): void {
    if (this.started) return;
    this.started = true;
    for (const s of this.sweeps.values()) this.schedule(s, s.def.initialDelayMs ?? 0);
  }

  /**
   * Stop scheduling new runs and wait (bounded) for in-flight ones. Returns
   * the names of sweeps still running when the bound expired.
   */
  async stop(waitMs = 30_000): Promise<string[]> {
    this.stopped = true;
    for (const s of this.sweeps.values()) {
      if (s.timer) { this.opts.clearTimeoutFn(s.timer); s.timer = null; }
    }
    const deadline = this.opts.now() + waitMs;
    while (this.opts.now() < deadline && [...this.sweeps.values()].some((s) => s.running)) {
      await new Promise<void>((r) => this.opts.setTimeoutFn(r, 100));
    }
    return [...this.sweeps.values()].filter((s) => s.running).map((s) => s.name);
  }

  stats(): SweepStats[] {
    return [...this.sweeps.values()].map(({ def: _d, timer: _t, settling: _s, ...rest }) => ({ ...rest }));
  }

  /** How many sweeps are executing right now (for the worker's status line). */
  get activeCount(): number {
    return this.running;
  }

  private schedule(s: SweepState, delayMs: number) {
    if (this.stopped) return;
    if (s.timer) this.opts.clearTimeoutFn(s.timer);
    s.timer = this.opts.setTimeoutFn(() => {
      s.timer = null;
      void this.run(s);
    }, Math.max(0, delayMs));
  }

  private async acquire(): Promise<void> {
    if (this.running < this.opts.maxConcurrent) { this.running++; return; }
    await new Promise<void>((resolve) => this.waiters.push(resolve));
    this.running++;
  }

  private release() {
    this.running--;
    const next = this.waiters.shift();
    if (next) next();
  }

  private async run(s: SweepState) {
    if (this.stopped) return;
    // Overlap guard: an overrun run from before is still settling — wait for it.
    if (s.settling) {
      try { await s.settling; } catch { /* already logged */ }
      s.settling = null;
      if (this.stopped) return;
    }
    await this.acquire();
    if (this.stopped) { this.release(); return; }

    const startedAt = this.opts.now();
    s.running = true;
    s.runs++;
    s.lastStartedAt = startedAt;
    const timeoutMs = s.def.timeoutMs ?? this.opts.defaultTimeoutMs;

    const p = s.def.fn().then(
      () => undefined,
      (e) => {
        s.errors++;
        this.opts.logError(`[sweep:${s.name}] error`, e);
      }
    );
    let overran = false;
    let timer: NodeJS.Timeout | null = null;
    const timeout = new Promise<"timeout">((resolve) => {
      timer = this.opts.setTimeoutFn(() => resolve("timeout"), timeoutMs);
    });
    const outcome = await Promise.race([p.then(() => "done" as const), timeout]);
    if (timer) this.opts.clearTimeoutFn(timer);
    if (outcome === "timeout") {
      overran = true;
      s.overruns++;
      this.opts.logError(
        `[sweep:${s.name}] overran its ${Math.round(timeoutMs / 1000)}s budget — slot released, next run waits for it to settle`
      );
      // Keep the promise around so the next scheduled run blocks on it.
      s.settling = p.finally(() => {
        s.running = false;
        s.lastDurationMs = this.opts.now() - startedAt;
        s.maxDurationMs = Math.max(s.maxDurationMs, s.lastDurationMs);
      });
    } else {
      s.running = false;
      s.lastDurationMs = this.opts.now() - startedAt;
      s.maxDurationMs = Math.max(s.maxDurationMs, s.lastDurationMs);
    }
    this.release();

    // Next run: interval measured from this run's START, never sooner than
    // now (a run longer than its interval goes again immediately once it has
    // settled — never concurrently with itself).
    const elapsed = this.opts.now() - startedAt;
    const delay = overran ? s.def.intervalMs : Math.max(0, s.def.intervalMs - elapsed);
    this.schedule(s, delay);
  }
}

