import { Prisma } from "@prisma/client";
import { db } from "./db";
import { priorityOf, PRIORITY_LABEL } from "../worker/scheduler";

/**
 * Job latency metrics — the query helper behind the admin "queue health" views.
 *
 * Two numbers matter to a customer pressing a button:
 *   queue wait = Job.startedAt - Job.createdAt   (how long before the worker picked it up)
 *   run time   = Job.finishedAt - Job.startedAt  (how long the action itself took)
 *
 * Both columns were added 2026-10-01 (see prisma/schema.prisma `Job`); rows
 * older than that have neither and are simply excluded — the pre-2026-10-01
 * `updatedAt - createdAt` figure mixed both numbers together and is not
 * comparable (that is why this helper does NOT fall back to it).
 *
 * Everything is one Postgres aggregate per call (percentile_cont over an
 * indexed (type, finishedAt) slice) — cheap enough to render on every admin
 * page load. Values are milliseconds.
 */

export type JobTypeMetrics = {
  type: string;
  priority: "interactive" | "normal" | "bulk";
  count: number;
  failed: number;
  queueWaitMs: { p50: number; p95: number; max: number };
  runMs: { p50: number; p95: number; max: number };
};

export type QueueSnapshot = {
  queued: number;
  running: number;
  /** Oldest QUEUED row's age in ms — the live "how far behind are we" number. */
  oldestQueuedMs: number | null;
  byType: Array<{ type: string; queued: number; running: number }>;
};

const n = (v: unknown) => (v == null ? 0 : Math.round(Number(v)));

/**
 * Per-type p50/p95/max of queue wait and run time for terminal jobs finished
 * within `windowHours` (default 24h). Sorted by count desc.
 */
export async function jobMetricsByType(windowHours = 24): Promise<JobTypeMetrics[]> {
  const since = new Date(Date.now() - windowHours * 3600_000);
  const rows = await db.$queryRaw<
    Array<{
      type: string; count: bigint; failed: bigint;
      qw50: number | null; qw95: number | null; qwmax: number | null;
      rt50: number | null; rt95: number | null; rtmax: number | null;
    }>
  >(Prisma.sql`
    SELECT
      "type"::text AS type,
      count(*)::bigint AS count,
      sum(CASE WHEN status = 'FAILED' THEN 1 ELSE 0 END)::bigint AS failed,
      percentile_cont(0.5)  WITHIN GROUP (ORDER BY extract(epoch FROM ("startedAt" - "createdAt")) * 1000) AS qw50,
      percentile_cont(0.95) WITHIN GROUP (ORDER BY extract(epoch FROM ("startedAt" - "createdAt")) * 1000) AS qw95,
      max(extract(epoch FROM ("startedAt" - "createdAt")) * 1000) AS qwmax,
      percentile_cont(0.5)  WITHIN GROUP (ORDER BY extract(epoch FROM ("finishedAt" - "startedAt")) * 1000) AS rt50,
      percentile_cont(0.95) WITHIN GROUP (ORDER BY extract(epoch FROM ("finishedAt" - "startedAt")) * 1000) AS rt95,
      max(extract(epoch FROM ("finishedAt" - "startedAt")) * 1000) AS rtmax
    FROM "Job"
    WHERE "finishedAt" >= ${since}
      AND "startedAt" IS NOT NULL
      AND status IN ('DONE', 'FAILED')
    GROUP BY "type"
    ORDER BY count DESC
  `);
  return rows.map((r) => ({
    type: r.type,
    priority: PRIORITY_LABEL[priorityOf(r.type)],
    count: Number(r.count),
    failed: Number(r.failed),
    queueWaitMs: { p50: n(r.qw50), p95: n(r.qw95), max: n(r.qwmax) },
    runMs: { p50: n(r.rt50), p95: n(r.rt95), max: n(r.rtmax) },
  }));
}

