new='''/**
 * One shared undici Agent for every Proxmox call (all nodes): keep-alive +
 * connection reuse come with it by default, so a burst of status polls does
 * not pay a TLS handshake per call. `connections` bounds the sockets per
 * origin so a fan-out can't open hundreds of sockets to one pveproxy (which
 * has its own small worker pool and would just queue them anyway).
 */
const insecureAgent = new Agent({
  connect: { rejectUnauthorized: false },
  connections: Math.max(2, Number(process.env.PROXMOX_MAX_SOCKETS_PER_NODE ?? 16)),
  keepAliveTimeout: 30_000,
});

/**
 * Hard ceiling on a single Proxmox API round-trip. Every PVE call used to be
 * unbounded: a wedged pveproxy (or a node whose network dropped mid-request)
 * would hang the caller — a job slot, a sweep, or a customer's dashboard
 * request — forever. Long operations (clone, vzdump, restore) are NOT affected:
 * those POSTs return a UPID immediately and progress is polled via waitForTask.
 */
export const PROXMOX_REQUEST_TIMEOUT_MS = Math.max(5_000, Number(process.env.PROXMOX_REQUEST_TIMEOUT_MS ?? 60_000));
'''
assert s.count(old)==1
s=s.replace(old,new,1)
old='''  const res = await undiciFetch(url, { method, headers, body, dispatcher: insecureAgent });
  const text = await res.text();'''
new='''  let res: Awaited<ReturnType<typeof undiciFetch>>;
  try {
    res = await undiciFetch(url, {
      method, headers, body, dispatcher: insecureAgent,
      signal: AbortSignal.timeout(PROXMOX_REQUEST_TIMEOUT_MS),
    });
  } catch (e: any) {
    if (e?.name === "TimeoutError" || e?.name === "AbortError") {
      throw new ProxmoxError(`PVE ${method} ${path} -> timed out after ${Math.round(PROXMOX_REQUEST_TIMEOUT_MS / 1000)}s`, 0, "request timeout");
    }
    throw e;
  }
  const text = await res.text();'''
assert s.count(old)==1
s=s.replace(old,new,1)
old='''export async function vmStatus(vmid: number): Promise<any> {
  return pve.get(`/nodes/${NODE}/qemu/${vmid}/status/current`);
}
'''
new='''export async function vmStatus(vmid: number): Promise<any> {
  return pve.get(`/nodes/${NODE}/qemu/${vmid}/status/current`);
}

/**
 * Short-TTL, in-flight-deduplicated `status/current` read for READ-ONLY
 * display paths (dashboard widgets, list pages) that fan out one call per VM
 * on every page load. Two requests for the same VM within `ttlMs` share one
 * Proxmox call; concurrent requests share the same in-flight promise. Never
 * use this where a fresh answer matters (power actions, waitForTask).
 *
 * `nodeKey` separates vmid spaces: vmids are per node and DO collide across
 * the fleet, so the cache key must carry the node.
 */
const statusCache = new Map<string, { at: number; p: Promise<any> }>();
export function vmStatusCached(
  conn: Pick<PveClient, "vmStatus"> & { node: string },
  vmid: number,
  ttlMs = 5_000
): Promise<any> {
  const key = `${conn.node}:${vmid}`;
  const now = Date.now();
  const hit = statusCache.get(key);
  if (hit && now - hit.at < ttlMs) return hit.p;
  const p = conn.vmStatus(vmid);
  statusCache.set(key, { at: now, p });
  // A failure must not be served from cache for the rest of the TTL.
  p.catch(() => { if (statusCache.get(key)?.p === p) statusCache.delete(key); });
  if (statusCache.size > 5000) {
    for (const [k, v] of statusCache) if (now - v.at >= ttlMs) statusCache.delete(k);
  }
  return p;
}
'''
assert s.count(old)==1
s=s.replace(old,new,1)
open(p,'w').write(s)
print('ok')
EOF
