import { test } from "node:test";
import assert from "node:assert/strict";
import { SweepRunner } from "../worker/sweeps.ts";

/**
 * worker/sweeps.ts — the background sweep runner that keeps housekeeping off
 * the job-claim path. Real timers with tiny intervals (tens of ms) — the
 * behaviours under test are ordering/overlap/limits, not wall-clock accuracy.
 */

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const quiet = { log: () => {}, logError: () => {} };

test("a sweep never overlaps itself: a run longer than its interval is not started again until it settles", async () => {
  let concurrent = 0;
  let maxConcurrent = 0;
  let runs = 0;
  const runner = new SweepRunner({ maxConcurrent: 4, ...quiet });
  runner.register({
    name: "slow",
    intervalMs: 10,
    fn: async () => {
      runs++;
      concurrent++;
      maxConcurrent = Math.max(maxConcurrent, concurrent);
      await sleep(60);
      concurrent--;
    },
  });
  runner.start();
  await sleep(250);
  await runner.stop(500);
  assert.equal(maxConcurrent, 1, "never two instances of one sweep");
  assert.ok(runs >= 2 && runs <= 5, `ran ${runs} times in 250ms with 60ms runs`);
});

test("global concurrency cap bounds how many different sweeps run at once; all still get to run", async () => {
  let concurrent = 0;
  let maxConcurrent = 0;
  const ran = new Set<string>();
  const runner = new SweepRunner({ maxConcurrent: 2, ...quiet });
  for (let i = 0; i < 6; i++) {
    runner.register({
      name: `s${i}`,
      intervalMs: 10_000,
      fn: async () => {
        ran.add(`s${i}`);
        concurrent++;
        maxConcurrent = Math.max(maxConcurrent, concurrent);
        await sleep(30);
        concurrent--;
      },
    });
  }
  runner.start();
  await sleep(300);
  await runner.stop(500);
  assert.equal(maxConcurrent, 2);
  assert.equal(ran.size, 6, "every registered sweep ran at boot");
});

test("a throwing sweep is isolated: counted as an error, other sweeps keep running, it is rescheduled", async () => {
  let okRuns = 0;
  let badRuns = 0;
  const runner = new SweepRunner({ maxConcurrent: 2, ...quiet });
  runner.register({ name: "bad", intervalMs: 20, fn: async () => { badRuns++; throw new Error("boom"); } });
  runner.register({ name: "ok", intervalMs: 20, fn: async () => { okRuns++; } });
  runner.start();
  await sleep(150);
  await runner.stop(200);
  const bad = runner.stats().find((s) => s.name === "bad")!;
  assert.ok(bad.errors >= 2, `bad errored ${bad.errors} times`);
  assert.equal(bad.errors, badRuns);
  assert.ok(okRuns >= 3, `ok ran ${okRuns} times alongside the failing one`);
});

test("overrun: the runner stops waiting after timeoutMs, frees the slot, records the overrun, and still won't overlap", async () => {
  let slowStarts = 0;
  let otherRuns = 0;
  let slowFinished = false;
  const runner = new SweepRunner({ maxConcurrent: 1, ...quiet });
  runner.register({
    name: "slow",
    intervalMs: 10,
    timeoutMs: 30,
    fn: async () => { slowStarts++; await sleep(200); slowFinished = true; },
  });
  runner.register({ name: "other", intervalMs: 10, fn: async () => { otherRuns++; } });
  runner.start();
  await sleep(120);
  // With maxConcurrent=1, "other" could only have run if "slow"'s slot was
  // released at its 30ms timeout rather than held for the full 200ms.
  assert.ok(otherRuns >= 2, `other ran ${otherRuns} times while slow was overrunning`);
  assert.equal(slowStarts, 1, "slow was not restarted while its first run was still settling");
  assert.equal(slowFinished, false);
  const st = runner.stats().find((s) => s.name === "slow")!;
  assert.equal(st.overruns, 1);
  assert.equal(st.running, true);
  await sleep(150);
  assert.equal(slowFinished, true);
  await runner.stop(500);
});

test("stop(): no new runs are scheduled after stop, and it waits (bounded) for in-flight runs", async () => {
  let runs = 0;
  const runner = new SweepRunner({ maxConcurrent: 2, ...quiet });
  runner.register({ name: "x", intervalMs: 5, fn: async () => { runs++; await sleep(40); } });
  runner.start();
  await sleep(20);
  const stillRunning = await runner.stop(500);
  const after = runs;
  assert.deepEqual(stillRunning, []);
  await sleep(60);
  assert.equal(runs, after, "nothing ran after stop()");
});

test("registering the same name twice is a programming error", () => {
  const runner = new SweepRunner({ maxConcurrent: 1, ...quiet });
  runner.register({ name: "dup", intervalMs: 1000, fn: async () => {} });
  assert.throws(() => runner.register({ name: "dup", intervalMs: 1000, fn: async () => {} }), /registered twice/);
});

