// READ-ONLY diagnosis: for the two servers whose sweeps log "All configured
// authentication methods failed", resolve the exact SSH target the platform
// dials (connectionTarget) and try each credential separately. Nothing is
// written; the remote command is `true`. Secrets are never printed.
import { db } from "/opt/nxeon/lib/db";
import { connectionTarget, serverRootPassword, serverManagementKey } from "/opt/nxeon/lib/sftp";
import { Client } from "ssh2";

async function tryAuth(host: string, port: number, auth: { password?: string; privateKey?: string }): Promise<string> {
  return new Promise((resolve) => {
    const c = new Client();
    const t = setTimeout(() => { try { c.end(); } catch {} resolve("timeout(15s)"); }, 15000);
    c.on("ready", () => { clearTimeout(t); c.end(); resolve("OK"); })
     .on("error", (e) => { clearTimeout(t); resolve(`ERR ${e.message}`); })
     .connect({ host, port, username: "root", readyTimeout: 15000, ...auth });
  });
}

async function main() {
  const ids = ["cmu3uc3gw1h98hl6obh28mwg8", "cmu9o3e830duahl79l1h2efr2"];
  for (const id of ids) {
    const s = await db.server.findUnique({
      where: { id },
      select: { id: true, hostname: true, status: true, vmid: true, sshPort: true, guestSshPort: true, rootPassword: true, rootPasswordEnc: true, sshManagementKeyEnc: true, createdAt: true,
        dedicatedIp: { select: { address: true } }, node: { select: { name: true, publicIp: true } } },
    });
    if (!s) { console.log(id, "not found"); continue; }
    const target = connectionTarget(s);
    const pw = serverRootPassword(s);
    const key = serverManagementKey(s);
    console.log(`\n== ${s.hostname} (${s.id}) node=${s.node?.name} status=${s.status} vmid=${s.vmid} created=${s.createdAt.toISOString()}`);
    console.log(`   target=${target?.host}:${target?.port} dedicated=${!!s.dedicatedIp} hasPassword=${!!pw} hasMgmtKey=${!!key}`);
    if (!target) continue;
    if (key) console.log(`   mgmt-key auth: ${await tryAuth(target.host, target.port, { privateKey: key })}`);
    if (pw) console.log(`   password auth: ${await tryAuth(target.host, target.port, { password: pw })}`);
    // Recent jobs that could have changed the password (PASSWORD_RESET / REINSTALL / retried PROVISION)
    const jobs = await db.job.findMany({ where: { serverId: id, type: { in: ["PROVISION", "REINSTALL", "PASSWORD_RESET", "GAME_REINSTALL"] } }, orderBy: { createdAt: "asc" }, select: { type: true, status: true, attempts: true, createdAt: true, error: true } });
    for (const j of jobs) console.log(`   job ${j.type} ${j.status} attempts=${j.attempts} ${j.createdAt.toISOString()} ${(j.error ?? "").slice(0, 120).replace(/\n/g, " ")}`);
  }
  await db.$disconnect();
}
main().catch((e) => { console.error(e); process.exit(1); });
EOF
