 *
 * SAFETY: refuses to run unless NXEON_SANDBOX=1 AND the DATABASE_URL database
 * name is not `nxeon`. It TRUNCATES Job/Server/User rows it created (prefixed
 * `lt-`) on every run — only ever point it at a scratch DB.
 *
 *   cd /opt/nxeon-wt-<short>
 *   NXEON_SANDBOX=1 NXEON_WORKER_NO_MAIN=1 DATABASE_URL=postgresql://.../nxeon_agt_<short> \
 *     npx tsx scripts/loadtest-queue.ts --matrix            # before/after table for 20/50/100
 *     npx tsx scripts/loadtest-queue.ts --n 50 --speed 30   # one run with the tuned defaults
 *     npx tsx scripts/loadtest-queue.ts --n 50 --legacy     # one run with the pre-2026-10-01 behaviour
 *
 * Flags:
 *   --n N            N simultaneous provisions + N restarts + N config applies (default 20)
 *   --bulk B         B BACKUP_CREATE + 2B GAME_UPDATE queued just before the burst (default N)
 *   --speed S        time compression: a 240s provision sleeps 240/S real seconds (default 30)
 *   --legacy         FIFO + per-server lock only, concurrency 8, no caps/priority (pre-2026-10-01)
 *   --stall-ms MS    legacy only: emulate inline sweeps — block claiming MS (simulated) every --stall-every
 *   --stall-every MS legacy only (default 60000 simulated)
 *   --concurrency/--bulk-cap/--per-node-cap/--per-node-heavy-cap/--per-user-soft   override limits
 *   --matrix         run legacy(stalls) vs tuned for n=20,50,100 and print a comparison table
 *   --json           print the summary as JSON too
 */
process.env.NXEON_WORKER_NO_MAIN = "1";

import { db } from "../lib/db";
import { WorkerLoop } from "../worker/index";
import {
  selectClaims, lockKeyFor, limitsFromEnv, priorityOf, PRIORITY_LABEL,
  type Candidate, type ActiveEntry, type SchedulerLimits, type Decision,
} from "../worker/scheduler";
import type { Job } from "@prisma/client";

// ---------------------------------------------------------------------------
// Guard rails
// ---------------------------------------------------------------------------
const dbName = (() => {
  try { return new URL(process.env.DATABASE_URL ?? "").pathname.replace(/^\//, ""); } catch { return ""; }
})();
if (process.env.NXEON_SANDBOX !== "1" || !dbName || dbName === "nxeon" || !/agt|test|load|scratch|sandbox|staging/i.test(dbName)) {
  console.error(`refusing to run: NXEON_SANDBOX must be 1 and DATABASE_URL must name a throwaway DB (got "${dbName || "?"}")`);
  process.exit(2);
}

// ---------------------------------------------------------------------------
// Args
// ---------------------------------------------------------------------------
const argv = process.argv.slice(2);
const flag = (k: string) => argv.includes(`--${k}`);
const num = (k: string, d: number) => { const i = argv.indexOf(`--${k}`); const v = i >= 0 ? Number(argv[i + 1]) : NaN; return Number.isFinite(v) ? v : d; };
const N = num("n", 20);
const BULK = num("bulk", N);
const SPEED = num("speed", 30);
const LEGACY = flag("legacy");
const STALL_MS = num("stall-ms", 0);
const STALL_EVERY = num("stall-every", 60_000);
const JSON_OUT = flag("json");

// ---------------------------------------------------------------------------
// Run-time model (simulated seconds) — lognormal around production medians.
// Source: prod Job table, DONE rows, last 14 days, p25 of updatedAt-createdAt
// as the run-time proxy (the p50 of that window still carried the pre-
// concurrency queue wait). PROVISION games wait on the install (~2x a VPS).
// ---------------------------------------------------------------------------
const RUN_MODEL: Record<string, { median: number; sigma: number }> = {
  PROVISION: { median: 240, sigma: 0.35 },
  GAME_POWER: { median: 25, sigma: 0.5 },
  GAME_CONFIG: { median: 20, sigma: 0.5 },
  REBOOT: { median: 22, sigma: 0.3 },
  BACKUP_CREATE: { median: 90, sigma: 0.6 },
  GAME_UPDATE: { median: 60, sigma: 0.7 },
  DELETE: { median: 20, sigma: 0.4 },
};
let seed = 1234567;
const rnd = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; };
const gauss = () => { const u = Math.max(rnd(), 1e-9), v = rnd(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v); };
const sampleRunSeconds = (type: string) => {
  const m = RUN_MODEL[type] ?? { median: 30, sigma: 0.5 };
  return m.median * Math.exp(m.sigma * gauss());
};
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

// ---------------------------------------------------------------------------
// Seed
// ---------------------------------------------------------------------------
const NODES = 5;
async function reset() {
  await db.$executeRawUnsafe(`DELETE FROM "Job" WHERE "serverId" IN (SELECT id FROM "Server" WHERE hostname LIKE 'lt-%') OR "serverId" IS NULL AND type = 'SYNC_FORWARDS' AND payload::text LIKE '%lt-%'`);
  await db.$executeRawUnsafe(`DELETE FROM "Server" WHERE hostname LIKE 'lt-%'`);
  await db.$executeRawUnsafe(`DELETE FROM "User" WHERE email LIKE 'lt-%@loadtest.invalid'`);
}

async function seedFixtures() {
  const plan = await db.plan.upsert({
    where: { slug: "lt-plan" }, update: {},
    create: { slug: "lt-plan", name: "lt plan", cpuCores: 2, ramMB: 4096, diskGB: 40, priceCents: 1000 },
  });
  const os = await db.osTemplate.upsert({
    where: { slug: "lt-os" }, update: {},
    create: { slug: "lt-os", name: "lt os", vmid: 9000 },
  });
  const nodes = [];
  for (let i = 0; i < NODES; i++) {
    nodes.push(await db.node.upsert({
      where: { name: `lt-node-${i}` }, update: {},
      create: { name: `lt-node-${i}`, pveNode: `lt${i}`, apiUrl: `https://10.255.${i}.1:8006`, tokenId: "lt", tokenSecret: "lt", publicIp: `198.51.100.${10 + i}` },
    }));
  }
  return { plan, os, nodes };
}

type Scenario = { provisions: number; restarts: number; configs: number; bulkBackups: number; bulkUpdates: number };

async function seedScenario(sc: Scenario) {
  await reset();
  const { plan, os, nodes } = await seedFixtures();
  const userCount = Math.max(4, Math.ceil(sc.provisions / 3));
  const users = [];
  for (let i = 0; i < userCount; i++) {
    users.push(await db.user.create({ data: { email: `lt-u${i}@loadtest.invalid`, passwordHash: "x", name: `lt user ${i}` } }));
  }
  // One "hog" account (users[0]) places 30% of the provisions — exercises fairness.
  const pickUser = (i: number) => (i % 10 < 3 ? users[0] : users[1 + (i % (users.length - 1))]);
  let srv = 0;
  const mkServer = (i: number, status: string) =>
    db.server.create({
      data: {
        name: `lt-${srv}`, hostname: `lt-${srv++}-${Date.now().toString(36)}`, status: status as never,
        userId: pickUser(i).id, planId: plan.id, osTemplateId: os.id, nodeId: nodes[i % NODES].id,
        vmid: status === "PENDING" ? null : 900000 + srv,
      },
    });
  // Bulk work queued FIRST (as the backup-schedule / game-update sweeps would).
  for (let i = 0; i < sc.bulkBackups; i++) {
    const s = await mkServer(1000 + i, "RUNNING");
    await db.job.create({ data: { type: "BACKUP_CREATE", serverId: s.id } });
  }
  for (let i = 0; i < sc.bulkUpdates; i++) {
    const s = await mkServer(2000 + i, "RUNNING");
    await db.job.create({ data: { type: "GAME_UPDATE", serverId: s.id } });
  }
  // The burst: everything created "at the same time".
  const burst: Array<{ type: string; serverId: string }> = [];
  for (let i = 0; i < sc.provisions; i++) burst.push({ type: "PROVISION", serverId: (await mkServer(i, "PENDING")).id });
  for (let i = 0; i < sc.restarts; i++) burst.push({ type: "GAME_POWER", serverId: (await mkServer(3000 + i, "RUNNING")).id });
  for (let i = 0; i < sc.configs; i++) burst.push({ type: "GAME_CONFIG", serverId: (await mkServer(4000 + i, "RUNNING")).id });
  // Interleave so FIFO order is realistic (not all provisions first).
  for (let i = burst.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [burst[i], burst[j]] = [burst[j], burst[i]]; }
  const t0 = new Date();
  await db.job.createMany({ data: burst.map((b, i) => ({ type: b.type as never, serverId: b.serverId, createdAt: new Date(t0.getTime() + i) })) });
  return { t0, total: burst.length + sc.bulkBackups + sc.bulkUpdates };
}

// ---------------------------------------------------------------------------
// Fake handlers: sleep the modelled run time, compressed by SPEED. The real
// runJob wrapper around them still does the DONE/FAILED/finishedAt writes.
// ---------------------------------------------------------------------------
const fakeHandlers: Record<string, (job: Job) => Promise<void>> = new Proxy({}, {
  get: (_t, type: string) => async (_job: Job) => { await sleep((sampleRunSeconds(type) * 1000) / SPEED); },
  has: () => true,
}) as Record<string, (job: Job) => Promise<void>>;

/** Pre-2026-10-01 behaviour: FIFO, per-server lock, flat concurrency. */
function legacySelect(candidates: Candidate[], active: Iterable<ActiveEntry>, lim: SchedulerLimits): Decision {
  const locked = new Set<string>();
  let total = 0;
  for (const a of active) { locked.add(a.lockKey); total++; }
  const claim: Candidate[] = [];
  const skipped: Decision["skipped"] = [];
  for (const c of [...candidates].sort((a, b) => a.createdAt.getTime() - b.createdAt.getTime())) {
    if (total >= lim.concurrency) { skipped.push({ id: c.id, reason: "concurrency" }); continue; }
    const k = lockKeyFor(c);
    if (locked.has(k)) { skipped.push({ id: c.id, reason: "lock" }); continue; }
    locked.add(k); total++; claim.push(c);
  }
  return { claim, skipped };
}

// ---------------------------------------------------------------------------
// Run one scenario, return the report
// ---------------------------------------------------------------------------
type Pct = { n: number; p50: number; p95: number; max: number };
const pct = (xs: number[]): Pct => {
  if (!xs.length) return { n: 0, p50: 0, p95: 0, max: 0 };
  const s = [...xs].sort((a, b) => a - b);
  const q = (p: number) => s[Math.min(s.length - 1, Math.floor(p * (s.length - 1)))];
  return { n: s.length, p50: q(0.5), p95: q(0.95), max: s[s.length - 1] };
};
const simSec = (ms: number) => Math.round((ms * SPEED) / 1000);

type Report = {
  label: string; n: number; limits: SchedulerLimits; legacy: boolean; stallMs: number;
  makespanSimSec: number;
  byType: Record<string, { queueWait: Pct; run: Pct }>;
  byPriority: Record<string, Pct>;
};

async function runScenario(label: string, sc: Scenario, limits: SchedulerLimits, legacy: boolean, stallMs: number): Promise<Report> {
  const { t0, total } = await seedScenario(sc);
  const loop = new WorkerLoop({ limits, pollMs: 100, handlers: fakeHandlers, select: legacy ? legacySelect : selectClaims, log: () => {} });

  // Drive ticks ourselves so the legacy baseline can emulate inline sweeps:
  // every STALL_EVERY simulated ms, claiming blocks for stallMs simulated ms —
  // exactly what the old loop did while ssh-health/player-tracking/billing ran.
  const start = Date.now();
  let nextStall = start + STALL_EVERY / SPEED;
  let done = false;
  const driver = (async () => {
    while (!done) {
      if (legacy && stallMs > 0 && Date.now() >= nextStall) {
        await sleep(stallMs / SPEED);
        nextStall = Date.now() + STALL_EVERY / SPEED;
      }
      let claimed = 0;
      try { claimed = await loop.tick(); } catch (e) { console.error("tick error", e); }
      if (claimed === 0) await sleep(100);
    }
  })();
  // Wait until every seeded job is terminal.
  for (;;) {
    const open = await db.job.count({ where: { status: { in: ["QUEUED", "RUNNING"] }, server: { hostname: { startsWith: "lt-" } } } });
    if (open === 0) break;
    await sleep(250);
  }
  done = true;
  await driver;
  const makespanMs = Date.now() - start;

  const rows = await db.job.findMany({
    where: { server: { hostname: { startsWith: "lt-" } } },
    select: { type: true, status: true, createdAt: true, startedAt: true, finishedAt: true },
  });
  if (rows.length !== total) console.warn(`expected ${total} jobs, found ${rows.length}`);
  const byType: Report["byType"] = {};
  const byPri: Record<string, number[]> = { interactive: [], normal: [], bulk: [] };
  const grouped = new Map<string, { qw: number[]; run: number[] }>();
  for (const r of rows) {
    if (!r.startedAt || !r.finishedAt) { console.warn(`job without timestamps: ${r.type} ${r.status}`); continue; }
    const qw = r.startedAt.getTime() - r.createdAt.getTime();
    const run = r.finishedAt.getTime() - r.startedAt.getTime();
    const g = grouped.get(r.type) ?? { qw: [], run: [] };
    g.qw.push(qw); g.run.push(run); grouped.set(r.type, g);
    byPri[PRIORITY_LABEL[priorityOf(r.type)]].push(qw);
  }
  for (const [type, g] of grouped) {
    const toSim = (p: Pct): Pct => ({ n: p.n, p50: simSec(p.p50), p95: simSec(p.p95), max: simSec(p.max) });
    byType[type] = { queueWait: toSim(pct(g.qw)), run: toSim(pct(g.run)) };
  }
  const byPriority: Report["byPriority"] = {};
  for (const [k, xs] of Object.entries(byPri)) { const p = pct(xs); byPriority[k] = { n: p.n, p50: simSec(p.p50), p95: simSec(p.p95), max: simSec(p.max) }; }
  void t0;
  return { label, n: sc.provisions, limits, legacy, stallMs, makespanSimSec: simSec(makespanMs), byType, byPriority };
}

function printReport(r: Report) {
  console.log(`\n=== ${r.label} — n=${r.n} ${r.legacy ? "LEGACY (FIFO, lock only" + (r.stallMs ? `, inline-sweep stalls ${r.stallMs / 1000}s/${STALL_EVERY / 1000}s` : "") + ")" : "TUNED"} ` +
    `concurrency=${r.limits.concurrency} bulkCap=${r.limits.bulkCap} perNode=${r.limits.perNodeCap} perNodeHeavy=${r.limits.perNodeHeavyCap} perUserSoft=${r.limits.perUserSoft} ===`);
  console.log(`makespan: ${r.makespanSimSec}s simulated (speed ×${SPEED})`);
  console.log("queue wait by priority (simulated seconds):");
  for (const [k, p] of Object.entries(r.byPriority)) console.log(`  ${k.padEnd(12)} n=${String(p.n).padStart(4)}  p50=${String(p.p50).padStart(5)}s  p95=${String(p.p95).padStart(5)}s  max=${String(p.max).padStart(5)}s`);
  console.log("by type:                queue-wait p50/p95/max        run p50/p95");
  for (const [t, v] of Object.entries(r.byType).sort((a, b) => priorityOf(a[0]) - priorityOf(b[0]))) {
    console.log(`  ${t.padEnd(14)} n=${String(v.queueWait.n).padStart(4)}  ${String(v.queueWait.p50).padStart(5)}/${String(v.queueWait.p95).padStart(5)}/${String(v.queueWait.max).padStart(5)}s` +
      `   ${String(v.run.p50).padStart(4)}/${String(v.run.p95).padStart(4)}s`);
  }
}

async function main() {
  const base = limitsFromEnv();
  const limits: SchedulerLimits = {
    concurrency: num("concurrency", LEGACY ? 8 : base.concurrency),
    bulkCap: num("bulk-cap", LEGACY ? 999 : base.bulkCap),
    perNodeCap: num("per-node-cap", LEGACY ? 999 : base.perNodeCap),
    perNodeHeavyCap: num("per-node-heavy-cap", LEGACY ? 999 : base.perNodeHeavyCap),
    perUserSoft: num("per-user-soft", LEGACY ? 999 : base.perUserSoft),
  };
  const scenarioFor = (n: number): Scenario => ({ provisions: n, restarts: n, configs: n, bulkBackups: BULK === N ? n : BULK, bulkUpdates: 2 * (BULK === N ? n : BULK) });
  const reports: Report[] = [];
  if (flag("matrix")) {
    for (const n of [20, 50, 100]) {
      reports.push(await runScenario("before", scenarioFor(n), { concurrency: 8, bulkCap: 999, perNodeCap: 999, perNodeHeavyCap: 999, perUserSoft: 999 }, true, STALL_MS || 45_000));
      reports.push(await runScenario("after", scenarioFor(n), base, false, 0));
    }
    for (const r of reports) printReport(r);
    console.log("\n=== SUMMARY (simulated seconds) — queue wait p50 / p95 ===");
    console.log("n    | mode   | interactive      | provision (normal) | bulk             | makespan");
    for (const r of reports) {
      const i = r.byPriority.interactive, p = r.byType.PROVISION?.queueWait ?? { p50: 0, p95: 0 }, b = r.byPriority.bulk;
      console.log(`${String(r.n).padEnd(4)} | ${r.label.padEnd(6)} | ${String(i.p50).padStart(5)} / ${String(i.p95).padStart(5)}s   | ${String(p.p50).padStart(5)} / ${String(p.p95).padStart(5)}s      | ${String(b.p50).padStart(5)} / ${String(b.p95).padStart(5)}s  | ${r.makespanSimSec}s`);
    }
  } else {
    const r = await runScenario(LEGACY ? "legacy" : "tuned", scenarioFor(N), limits, LEGACY, STALL_MS);
    reports.push(r);
    printReport(r);
  }
  if (JSON_OUT) console.log(JSON.stringify(reports, null, 2));
  await reset();
  await db.$disconnect();
}

main().catch((e) => { console.error(e); process.exit(1); });

