// interruption fails the job. serverId-null jobs so no fixtures are needed.
process.env.NXEON_WORKER_NO_MAIN = "1";
import { db } from "/opt/nxeon-wt-concur/lib/db";
import { reapStuckJobs, requeueInterruptedJob } from "/opt/nxeon-wt-concur/worker/index";
async function main() {
  await db.job.deleteMany({ where: { type: "STAGING_CONTROL", serverId: null } });
  const a = await db.job.create({ data: { type: "STAGING_CONTROL", status: "RUNNING", attempts: 1, payload: { action: "start" }, startedAt: new Date() } });
  const b = await db.job.create({ data: { type: "STAGING_CONTROL", status: "RUNNING", attempts: 3, payload: { action: "stop", _restarts: 3 } } });
  const c = await db.job.create({ data: { type: "STAGING_CONTROL", status: "RUNNING", attempts: 0, payload: "weird-string" } });
  await reapStuckJobs();
  for (const id of [a.id, b.id, c.id]) {
